/**
 * Shared helpers for the JSON shaped payloads the waveform feature passes
 * between the page owner, the attachment store and the transport layer.
 */

export type JsonMap = Record<string, Object>;

export function jsonMap(keys: string[] = [], values: Object[] = []): JsonMap {
  const value: JsonMap = JSON.parse('{}') as JsonMap;
  for (let index = 0; index < keys.length; index++) {
    value[keys[index]] = values[index];
  }
  return value;
}

export function cloneMap(value: JsonMap): JsonMap {
  return JSON.parse(JSON.stringify(value)) as JsonMap;
}

export function cloneNumbers(values: number[]): number[] {
  return JSON.parse(JSON.stringify(values)) as number[];
}

export function asMap(value: Object | undefined): JsonMap {
  return value !== undefined && value !== null && !Array.isArray(value) ? value as JsonMap : jsonMap();
}

export function asMaps(value: Object | undefined): JsonMap[] {
  return Array.isArray(value) ? (value as Object[]).map((item: Object): JsonMap => asMap(item)) : [];
}

export function asNumbers(value: Object | undefined): number[] {
  return Array.isArray(value) ? (value as Object[]).map((item: Object): number => Number(item)) : [];
}

export function mapText(source: JsonMap, key: string): string {
  const item: Object = source[key];
  return typeof item === 'string' ? item : '';
}

export function mapNumber(source: JsonMap, key: string): number {
  const item: Object = source[key];
  return typeof item === 'number' ? item : 0;
}

export function mapBoolean(source: JsonMap, key: string): boolean {
  const item: Object = source[key];
  return typeof item === 'boolean' ? item : false;
}

export function isEmptyMap(source: JsonMap): boolean {
  return Object.keys(source).length === 0;
}

export function isPresent(value: Object | undefined): boolean {
  return value !== undefined && value !== null;
}

import { JsonMap, jsonMap } from './JsonMap';

/**
 * Ordered log of the side effects a waveform flow performed. The recorder keeps
 * the observed ordering (compress before waveform generation before upload)
 * observable to the page and to the attachment upload graph.
 */
export class EffectRecorder {
  private effects: JsonMap[] = [];

  record(name: string, attachmentId: string): void {
    this.effects.push(jsonMap(['name', 'attachmentId'], [name, attachmentId]));
  }

  count(name: string): number {
    let total: number = 0;
    for (let index = 0; index < this.effects.length; index++) {
      const effect: JsonMap = this.effects[index];
      const item: Object = effect['name'];
      if (typeof item === 'string' && item === name) {
        total++;
      }
    }
    return total;
  }

  includes(name: string, attachmentId: string): boolean {
    for (let index = 0; index < this.effects.length; index++) {
      const effect: JsonMap = this.effects[index];
      const effectName: Object = effect['name'];
      const effectAttachment: Object = effect['attachmentId'];
      if (typeof effectName === 'string' && effectName === name
        && typeof effectAttachment === 'string' && effectAttachment === attachmentId) {
        return true;
      }
    }
    return false;
  }

  reset(): void {
    this.effects = [];
  }

  snapshot(): JsonMap[] {
    return JSON.parse(JSON.stringify(this.effects)) as JsonMap[];
  }
}

/** Waveform sizing constants shared by generation, transport and rendering. */

/** Number of bars a locally generated waveform carries. */
export const GENERATED_BAR_COUNT: number = 50;

/** Bar count the voice note waveform UI always renders, whatever arrived on the wire. */
export const RENDER_BAR_COUNT: number = 50;

/** Largest number of bars the service accepts from a remote sender. */
export const SERVICE_WAVEFORM_BAR_LIMIT: number = 100;

/** Waveform magnitudes are unsigned bytes: silence is 0, full scale is 255. */
export const MAX_BAR_MAGNITUDE: number = 255;

/**
 * Waveform generation is only ever attached to audio media. Everything else
 * (images, documents, video) keeps its ordinary upload chain untouched.
 */
export function isAudioAttachment(contentType: string): boolean {
  const type: string = contentType.toLowerCase();
  if (type.length === 0) {
    return false;
  }
  if (type.startsWith('audio/')) {
    return true;
  }
  return type === 'application/ogg' || type === 'application/x-ogg' || type.indexOf('opus') >= 0;
}

import { GENERATED_BAR_COUNT } from './WaveformLimits';

function isUsableMagnitude(value: number): boolean {
  return value === value && value < Infinity && value > -Infinity;
}

/** Keeps a magnitude inside the unsigned 0..255 waveform range. */
export function clampMagnitude(value: number): number {
  if (!isUsableMagnitude(value)) {
    return 0;
  }
  const rounded: number = Math.round(value);
  return rounded < 0 ? 0 : (rounded > 255 ? 255 : rounded);
}

/** True when every magnitude is an unsigned byte value that the renderer accepts. */
export function areValidMagnitudes(values: number[]): boolean {
  for (let index = 0; index < values.length; index++) {
    const value: number = values[index];
    if (!isUsableMagnitude(value)) {
      return false;
    }
    if (value < 0 || value > 255 || Math.round(value) !== value) {
      return false;
    }
  }
  return true;
}

/** Normalizes an unsigned magnitude to the 0..1 range used by the waveform UI. */
export function normalizeMagnitude(value: number): number {
  return clampMagnitude(value) / 255;
}

/** A locally generated waveform whose bar count still matches the current release. */
export function isCurrentGeneratedBarCount(barCount: number): boolean {
  return barCount === GENERATED_BAR_COUNT;
}

import { JsonMap, asMaps, asNumbers, cloneNumbers, jsonMap, mapBoolean, mapNumber, mapText } from '../common/JsonMap';
import { isCurrentGeneratedBarCount } from './WaveformMagnitude';

/**
 * Decodes the magnitudes of a waveform payload. Waveforms reach us in three
 * interchangeable shapes: an explicit magnitude list, a run length encoded list
 * of `{ value, count }` segments, or a uniform `{ barCount, fill }` description.
 */
export function decodeWaveformMagnitudes(source: JsonMap): number[] {
  const explicit: number[] = asNumbers(source['bytes']);
  if (explicit.length > 0) {
    return explicit;
  }
  const segments: JsonMap[] = asMaps(source['segments']);
  if (segments.length > 0) {
    const expanded: number[] = [];
    for (let index = 0; index < segments.length; index++) {
      const segment: JsonMap = segments[index];
      const count: number = mapNumber(segment, 'count');
      const value: number = mapNumber(segment, 'value');
      for (let bar = 0; bar < count; bar++) {
        expanded.push(value);
      }
    }
    return expanded;
  }
  const barCount: number = mapNumber(source, 'barCount');
  if (barCount > 0) {
    const fill: number = mapNumber(source, 'fill');
    const uniform: number[] = [];
    for (let bar = 0; bar < barCount; bar++) {
      uniform.push(fill);
    }
    return uniform;
  }
  return [];
}

function decodeTransportMagnitudes(value: Object | undefined): number[] {
  if (Array.isArray(value)) {
    return asNumbers(value);
  }
  return decodeWaveformMagnitudes(value as JsonMap);
}

function resolveDurationSeconds(source: JsonMap): number {
  if (source['durationSeconds'] !== undefined) {
    return mapNumber(source, 'durationSeconds');
  }
  return mapNumber(source, 'durationUs') / 1000000;
}

/**
 * The waveform row that belongs to one attachment. Sender provided magnitudes
 * are stored verbatim and are never rewritten by generation or rendering.
 */
export class WaveformRecord {
  attachmentId: string = '';
  bytes: number[] = [];
  durationSeconds: number = 0;
  durationUs: number = 0;
  senderProvided: boolean = false;

  constructor(attachmentId: string, bytes: number[], durationSeconds: number, senderProvided: boolean) {
    this.attachmentId = attachmentId;
    this.bytes = bytes;
    this.durationSeconds = durationSeconds;
    this.durationUs = Math.round(durationSeconds * 1000000);
    this.senderProvided = senderProvided;
  }

  barCount(): number {
    return this.bytes.length;
  }

  /** A waveform that came from a sender is retained as-is, whatever its bar count is. */
  isSenderProvided(): boolean {
    return this.senderProvided;
  }

  /** An empty row is the failure marker of an interrupted generation, not silence. */
  isPlaceholder(): boolean {
    return !this.senderProvided && this.bytes.length === 0;
  }

  /** Locally generated rows whose bar count predates the current release are stale. */
  isObsoleteGenerated(): boolean {
    return !this.senderProvided && this.bytes.length > 0 && !isCurrentGeneratedBarCount(this.bytes.length);
  }

  isRenderable(): boolean {
    return this.bytes.length > 0;
  }

  /** True when this row can be shipped or rendered without touching the decoder. */
  isUsable(): boolean {
    return this.isRenderable() && (this.senderProvided || isCurrentGeneratedBarCount(this.bytes.length));
  }

  origin(): string {
    return this.senderProvided ? 'sender' : 'generated';
  }

  belongsTo(attachmentId: string): boolean {
    return this.attachmentId.length === 0 || this.attachmentId === attachmentId;
  }

  toPersistence(): JsonMap {
    return jsonMap(['attachmentId', 'bytes', 'barCount', 'durationSeconds', 'durationUs', 'senderProvided', 'origin'],
      [this.attachmentId, cloneNumbers(this.bytes), this.bytes.length,
        this.durationSeconds, this.durationUs, this.senderProvided, this.origin()]);
  }

  /** Builds a row from any of the stored waveform shapes. */
  static fromStored(attachmentId: string, stored: Object | undefined): WaveformRecord {
    if (Array.isArray(stored)) {
      return new WaveformRecord(attachmentId, asNumbers(stored), 0, false);
    }
    const source: JsonMap = stored === undefined || stored === null ? jsonMap() : stored as JsonMap;
    return new WaveformRecord(attachmentId, decodeWaveformMagnitudes(source),
      resolveDurationSeconds(source), mapBoolean(source, 'senderProvided'));
  }

  /** Builds a sender provided row from an incoming attachment pointer, bytes untouched. */
  static fromTransport(attachmentId: string, pointer: JsonMap): WaveformRecord {
    return new WaveformRecord(attachmentId, decodeTransportMagnitudes(pointer['audioWaveform']),
      mapNumber(pointer, 'audioDurationSeconds'), true);
  }

  static empty(attachmentId: string): WaveformRecord {
    return new WaveformRecord(attachmentId, [], 0, false);
  }

  static describe(attachmentId: string): JsonMap {
    return jsonMap(['attachmentId'], [attachmentId]);
  }
}

