import { GENERATED_BAR_COUNT, MAX_BAR_MAGNITUDE } from './WaveformLimits';
import { clampMagnitude } from './WaveformMagnitude';
import { WaveformRecord } from './WaveformRecord';

/**
 * Turns decoded PCM into the bounded waveform a voice note carries. Bars are
 * derived from decoded samples only (never from encoded byte positions), so a
 * container change cannot shift the shape, and the result is deterministic:
 * silence produces zero magnitude, full scale produces the maximum magnitude.
 */
export class WaveformGenerator {
  /**
   * Returns undefined when there is nothing decodable to derive a waveform
   * from; the caller keeps the empty generation placeholder in that case.
   */
  generate(attachmentId: string, samples: number[], durationUs: number): WaveformRecord | undefined {
    if (samples.length === 0 || durationUs <= 0) {
      return undefined;
    }
    const levels: number[] = this.bucketLevels(samples, GENERATED_BAR_COUNT);
    let loudest: number = 0;
    for (let index = 0; index < levels.length; index++) {
      loudest = Math.max(loudest, levels[index]);
    }
    const scale: number = loudest > 0 ? MAX_BAR_MAGNITUDE / loudest : 0;
    const bars: number[] = [];
    for (let index = 0; index < levels.length; index++) {
      bars.push(clampMagnitude(levels[index] * scale));
    }
    return new WaveformRecord(attachmentId, bars, durationUs / 1000000, false);
  }

  /** Mean absolute sample level of each bucket of decoded audio. */
  private bucketLevels(samples: number[], barCount: number): number[] {
    const levels: number[] = [];
    const length: number = samples.length;
    for (let bar = 0; bar < barCount; bar++) {
      const start: number = Math.floor(bar * length / barCount);
      let end: number = Math.min(length, Math.floor((bar + 1) * length / barCount));
      if (end <= start) {
        end = Math.min(length, start + 1);
      }
      let sum: number = 0;
      for (let index = start; index < end; index++) {
        sum += Math.abs(samples[index]);
      }
      levels.push(end > start ? sum / (end - start) : 0);
    }
    return levels;
  }
}

import { RENDER_BAR_COUNT } from './WaveformLimits';
import { clampMagnitude, normalizeMagnitude } from './WaveformMagnitude';
import { WaveformRecord } from './WaveformRecord';

/**
 * Turns a stored waveform into the fixed size bar list the voice note waveform
 * UI draws. Transported bars are read as unsigned magnitudes and resampled with
 * deterministic bucket averages, so a sender waveform renders identically
 * whether it carries 4, 50 or 100 bars and whether or not the media file is
 * available locally.
 */
export class WaveformRenderer {
  bars(record: WaveformRecord, barCount: number = RENDER_BAR_COUNT): number[] {
    const source: number[] = record.bytes;
    if (barCount <= 0 || source.length === 0) {
      return [];
    }
    if (source.length === barCount) {
      const copy: number[] = [];
      for (let index = 0; index < source.length; index++) {
        copy.push(clampMagnitude(source[index]));
      }
      return copy;
    }
    const length: number = source.length;
    const resampled: number[] = [];
    for (let bar = 0; bar < barCount; bar++) {
      let start: number = Math.floor(bar * length / barCount);
      let end: number = Math.floor((bar + 1) * length / barCount);
      if (end <= start) {
        end = Math.min(length, start + 1);
      }
      if (start >= length) {
        start = length - 1;
      }
      if (end > length) {
        end = length;
      }
      let sum: number = 0;
      for (let index = start; index < end; index++) {
        sum += clampMagnitude(source[index]);
      }
      resampled.push(clampMagnitude(end > start ? sum / (end - start) : 0));
    }
    return resampled;
  }

  /** The rendered bars normalized to 0..1 for the waveform view. */
  normalized(record: WaveformRecord, barCount: number = RENDER_BAR_COUNT): number[] {
    return this.bars(record, barCount).map((value: number): number => normalizeMagnitude(value));
  }
}

import { preferences } from '@kit.ArkData';
import { JsonMap, jsonMap, mapText } from '../common/JsonMap';
import { WaveformRecord } from './WaveformRecord';

const WAVEFORM_KEY: string = 'waveform';

/**
 * Persistence for the waveform row that belongs to the current attachment. A
 * row is written as a single value so that recovery replaces the whole row
 * atomically instead of leaving a half written waveform behind.
 */
export class WaveformStore {
  private store: preferences.Preferences;

  constructor(store: preferences.Preferences) {
    this.store = store;
  }

  async clear(): Promise<void> {
    await this.store.clear();
    await this.store.flush();
  }

  async flush(): Promise<void> {
    await this.store.flush();
  }

  async writeRecord(record: WaveformRecord): Promise<void> {
    await this.store.put(WAVEFORM_KEY, JSON.stringify(record.toPersistence()));
    await this.store.flush();
  }

  async readRecord(): Promise<WaveformRecord | undefined> {
    const raw: preferences.ValueType = await this.store.get(WAVEFORM_KEY, '');
    if (typeof raw !== 'string' || raw.length === 0) {
      return undefined;
    }
    return this.parseRow(raw);
  }

  private parseRow(raw: string): WaveformRecord | undefined {
    try {
      const row: JsonMap = JSON.parse(raw) as JsonMap;
      return WaveformRecord.fromStored(mapText(row, 'attachmentId'), row);
    } catch (error) {
      console.warn('[waveform] dropping unreadable waveform row: ' + JSON.stringify(error));
      return undefined;
    }
  }

  /** Snapshot of the persisted row, used by the attachment view after a reload. */
  snapshot(record: WaveformRecord | undefined): JsonMap {
    return record === undefined ? jsonMap() : jsonMap(['waveform'], [record.toPersistence()]);
  }
}

import { EffectRecorder } from '../common/EffectRecorder';
import { JsonMap, asMap, cloneNumbers, jsonMap, mapBoolean, mapNumber, mapText } from '../common/JsonMap';
import { WaveformRecord, decodeWaveformMagnitudes } from './WaveformRecord';

/**
 * The backup artifact for one attachment. Export writes the waveform into the
 * backup payload verbatim, restore reads it back and keeps the remote origin so
 * a restored sender waveform is never mistaken for a local cache entry.
 */
export class WaveformBackupFile {
  private payload: JsonMap = jsonMap();

  reset(): void {
    this.payload = jsonMap();
  }

  isEmpty(): boolean {
    return Object.keys(this.payload).length === 0;
  }

  /** Writes the backup entry and returns the exported attachment pointer. */
  exportAttachment(attachment: JsonMap, record: WaveformRecord | undefined): JsonMap {
    const pointer: JsonMap = jsonMap();
    const contentType: string = mapText(attachment, 'contentType');
    if (contentType.length > 0) {
      pointer['contentType'] = contentType;
    }
    const cdnKey: string = mapText(attachment, 'cdnKey');
    if (cdnKey.length > 0) {
      pointer['cdnKey'] = cdnKey;
    }
    if (record !== undefined) {
      pointer['attachmentId'] = record.attachmentId;
      pointer['barCount'] = record.barCount();
      pointer['audioWaveform'] = cloneNumbers(record.bytes);
      pointer['audioDurationSeconds'] = record.durationSeconds;
      pointer['senderProvided'] = record.senderProvided;
    }
    this.payload = jsonMap(['version', 'attachment'], [1, pointer]);
    return pointer;
  }

  restoreAttachment(): WaveformRecord | undefined {
    const pointer: JsonMap = asMap(this.payload['attachment']);
    const waveform: Object | undefined = pointer['audioWaveform'];
    if (waveform === undefined || waveform === null) {
      return undefined;
    }
    const bytes: number[] = Array.isArray(waveform) ? asNumbers(waveform) : decodeWaveformMagnitudes(asMap(waveform));
    return new WaveformRecord(mapText(pointer, 'attachmentId'), bytes,
      mapNumber(pointer, 'audioDurationSeconds'), mapBoolean(pointer, 'senderProvided'));
  }
}

