import { EffectRecorder } from '../common/EffectRecorder';
import { WaveformGenerator } from './WaveformGenerator';
import { WaveformRecord } from './WaveformRecord';
import { WaveformStore } from './WaveformStore';

/**
 * Runs one waveform generation attempt for an attachment.
 *
 * The attempt first parks an explicit empty row so that an interrupted or failed
 * run leaves a recognizable failure marker behind instead of a waveform that
 * looks like silence, then decodes the local audio and replaces the whole row
 * with the generated waveform. A failed attempt keeps the placeholder so the
 * next request with readable media can retry exactly once.
 */
export class WaveformGenerationService {
  private store: WaveformStore;
  private recorder: EffectRecorder;
  private generator: WaveformGenerator;

  constructor(store: WaveformStore, recorder: EffectRecorder, generator: WaveformGenerator) {
    this.store = store;
    this.recorder = recorder;
    this.generator = generator;
  }

  /**
   * @param markPlaceholder parks the empty generation marker first; upload
   *        preparation needs it, a plain render refresh does not.
   */
  async run(attachmentId: string, samples: number[], durationUs: number, markPlaceholder: boolean): Promise<WaveformRecord | undefined> {
    if (markPlaceholder) {
      this.recorder.record('persistGenerationPlaceholder', attachmentId);
      await this.store.writeRecord(WaveformRecord.empty(attachmentId));
    }
    this.recorder.record('decodeAudio', attachmentId);
    const record: WaveformRecord | undefined = this.generator.generate(attachmentId, samples, durationUs);
    if (record === undefined) {
      return undefined;
    }
    await this.store.writeRecord(record);
    this.recorder.record('persistGeneratedWaveform', attachmentId);
    return record;
  }
}

import { JsonMap, asMap, isEmptyMap, jsonMap, mapNumber, mapText } from '../common/JsonMap';
import { areValidMagnitudes } from './WaveformMagnitude';
import { WaveformRecord, decodeWaveformMagnitudes } from './WaveformRecord';

/** Result of validating the waveform metadata of an incoming attachment pointer. */
export class IncomingWaveformOutcome {
  accepted: boolean = false;
  reason: string = '';
  barCount: number = 0;
  limit: number = 0;
  durationSeconds: number = 0;

  constructor(limit: number) {
    this.limit = limit;
  }

  toMap(): JsonMap {
    return jsonMap(['accepted', 'reason', 'barCount', 'limit', 'durationSeconds'],
      [this.accepted, this.reason, this.barCount, this.limit, this.durationSeconds]);
  }
}

/**
 * Envelope validation for incoming attachment pointers. Waveform metadata is
 * checked before the attachment is persisted or handed to the renderer, so a
 * malformed or oversized sender payload can never contaminate attachment state.
 */
export class IncomingWaveformValidator {
  static validate(pointer: JsonMap, limit: number): IncomingWaveformOutcome {
    const outcome: IncomingWaveformOutcome = new IncomingWaveformOutcome(limit);
    if (isEmptyMap(pointer)) {
      outcome.reason = 'missing_attachment_pointer';
      return outcome;
    }
    if (mapText(pointer, 'cdnKey').length === 0) {
      outcome.reason = 'missing_cdn_key';
      return outcome;
    }
    const waveform: Object | undefined = pointer['audioWaveform'];
    if (waveform === undefined || waveform === null) {
      outcome.accepted = true;
      return outcome;
    }
    const bytes: number[] = Array.isArray(waveform) ? asNumbersOf(waveform) : decodeWaveformMagnitudes(asMap(waveform));
    outcome.barCount = bytes.length;
    if (outcome.barCount === 0) {
      outcome.reason = 'malformed_audio_waveform';
      return outcome;
    }
    if (!areValidMagnitudes(bytes)) {
      outcome.reason = 'malformed_audio_waveform';
      return outcome;
    }
    if (outcome.barCount > outcome.limit) {
      outcome.reason = 'audio_waveform_too_large';
      return outcome;
    }
    const duration: number = mapNumber(pointer, 'audioDurationSeconds');
    if (!(duration > 0)) {
      outcome.reason = 'missing_audio_duration';
      return outcome;
    }
    outcome.durationSeconds = duration;
    outcome.accepted = true;
    return outcome;
  }
}

function asNumbersOf(value: Object): number[] {
  const items: Object[] = value as Object[];
  const result: number[] = [];
  for (let index = 0; index < items.length; index++) {
    result.push(Number(items[index]));
  }
  return result;
}

/** Extracts the accepted sender waveform, or undefined when validation failed. */
export function acceptedSenderRecord(attachmentId: string, pointer: JsonMap, limit: number): WaveformRecord | undefined {
  const outcome: IncomingWaveformOutcome = IncomingWaveformValidator.validate(pointer, limit);
  if (!outcome.accepted) {
    return undefined;
  }
  if (pointer['audioWaveform'] === undefined || pointer['audioWaveform'] === null) {
    return undefined;
  }
  return WaveformRecord.fromTransport(attachmentId, pointer);
}

