import { JsonMap, jsonMap } from '../common/JsonMap';
import { isAudioAttachment } from '../waveform/WaveformLimits';

/**
 * Upload chain of a single attachment. Audio attachments hold the upload until
 * their waveform has been generated; every other attachment runs its ordinary
 * compress then upload chain and never acquires waveform work.
 */
export class AttachmentUploadChain {
  readonly attachmentId: string;
  readonly audio: boolean;

  private compressed: boolean = false;
  private waveformResolved: boolean = false;
  private waveformHeld: boolean = false;
  private waveformFailed: boolean = false;
  private waveformSkipped: boolean = false;
  private uploadStarted: boolean = false;

  constructor(attachmentId: string, contentType: string) {
    this.attachmentId = attachmentId;
    this.audio = isAudioAttachment(contentType);
  }

  isAudio(): boolean {
    return this.audio;
  }

  isCompressed(): boolean {
    return this.compressed;
  }

  markCompressed(): void {
    this.compressed = true;
  }

  /** Audio upload is now waiting for its waveform dependency. */
  holdWaveformGeneration(): void {
    if (!this.audio) {
      return;
    }
    this.waveformHeld = true;
  }

  resolveWaveform(): void {
    this.waveformHeld = false;
    this.waveformFailed = false;
    this.waveformResolved = true;
  }

  failWaveformGeneration(): void {
    this.waveformHeld = false;
    this.waveformFailed = true;
  }

  skipWaveformGeneration(): void {
    this.waveformSkipped = true;
    this.waveformResolved = true;
  }

  isWaveformResolved(): boolean {
    return this.waveformResolved;
  }

  isWaveformPending(): boolean {
    return this.audio && !this.waveformResolved;
  }

  isUploadStarted(): boolean {
    return this.uploadStarted;
  }

  markUploadStarted(): void {
    this.uploadStarted = true;
  }

  snapshot(): JsonMap {
    return jsonMap(['compression', 'waveformGeneration', 'upload'],
      [this.compressed ? 'complete' : 'pending', this.waveformStatus(),
        this.uploadStatus()]);
  }

  private waveformStatus(): string {
    if (this.waveformSkipped) {
      return 'not_scheduled';
    }
    if (this.waveformFailed) {
      return 'failed';
    }
    if (this.waveformResolved) {
      return 'complete';
    }
    return this.waveformHeld ? 'pending' : 'not_scheduled';
  }

  private uploadStatus(): string {
    if (this.uploadStarted) {
      return 'complete';
    }
    return this.isWaveformPending() ? 'blocked' : 'not_started';
  }
}

import { EffectRecorder } from '../common/EffectRecorder';
import { JsonMap, jsonMap, mapText } from '../common/JsonMap';
import { WaveformGenerationService } from '../waveform/WaveformGenerationService';
import { WaveformRecord } from '../waveform/WaveformRecord';
import { AttachmentUploadChain } from './AttachmentUploadChain';

/**
 * Runs the attachment upload graph.
 *
 * Compression always comes first. For audio the graph then parks on the
 * waveform dependency: releasing the generation worker resumes the very same
 * chain, so an attachment is never uploaded twice and an unrelated non-audio
 * attachment is never blocked by an audio waveform that is still pending.
 */
export class AttachmentUploadGraph {
  private recorder: EffectRecorder;
  private generation: WaveformGenerationService;
  private order: string[] = [];
  private sources: Map<string, JsonMap> = new Map();
  private chains: Map<string, AttachmentUploadChain> = new Map();

  constructor(recorder: EffectRecorder, generation: WaveformGenerationService) {
    this.recorder = recorder;
    this.generation = generation;
  }

  reset(): void {
    this.order = [];
    this.sources.clear();
    this.chains.clear();
  }

  /** Enters the chain for one attachment: compress, then waveform, then upload. */
  start(attachment: JsonMap, hasUsableWaveform: boolean): AttachmentUploadChain {
    const attachmentId: string = mapText(attachment, 'id');
    let chain: AttachmentUploadChain | undefined = this.chains.get(attachmentId);
    if (chain === undefined) {
      chain = new AttachmentUploadChain(attachmentId, mapText(attachment, 'contentType'));
      this.chains.set(attachmentId, chain);
      this.sources.set(attachmentId, attachment);
      this.order.push(attachmentId);
    }
    if (!chain.isCompressed()) {
      this.recorder.record('compressAttachment', attachmentId);
      chain.markCompressed();
    }
    if (chain.isAudio()) {
      if (chain.isWaveformResolved() || hasUsableWaveform) {
        chain.resolveWaveform();
      } else {
        chain.holdWaveformGeneration();
      }
    } else {
      chain.skipWaveformGeneration();
    }
    this.runUpload(chain);
    return chain;
  }

  /** Releases the waveform worker of one attachment and resumes its chain. */
  async release(attachmentId: string, samples: number[], durationUs: number): Promise<AttachmentUploadChain | undefined> {
    if (!this.chains.has(attachmentId)) {
      const source: JsonMap | undefined = this.sources.get(attachmentId);
      if (source === undefined) {
        return undefined;
      }
      this.start(source, false);
    }
    const chain: AttachmentUploadChain | undefined = this.chains.get(attachmentId);
    if (chain === undefined) {
      return undefined;
    }
    if (chain.isAudio() && !chain.isWaveformResolved()) {
      const record: WaveformRecord | undefined =
        await this.generation.run(attachmentId, samples, durationUs, true);
      if (record !== undefined) {
        chain.resolveWaveform();
      } else {
        chain.failWaveformGeneration();
      }
    }
    this.runUpload(chain);
    return chain;
  }

  /** Releases every audio attachment that is still parked on its waveform. */
  async releasePendingAudio(samples: number[], durationUs: number): Promise<void> {
    const pending: string[] = [];
    for (let index = 0; index < this.order.length; index++) {
      const chain: AttachmentUploadChain | undefined = this.chains.get(this.order[index]);
      if (chain !== undefined && chain.isWaveformPending()) {
        pending.push(chain.attachmentId);
      }
    }
    for (let index = 0; index < pending.length; index++) {
      await this.release(pending[index], samples, durationUs);
    }
  }

  snapshot(): JsonMap {
    const result: JsonMap = jsonMap();
    for (let index = 0; index < this.order.length; index++) {
      const chain: AttachmentUploadChain | undefined = this.chains.get(this.order[index]);
      if (chain !== undefined) {
        result[chain.attachmentId] = chain.snapshot();
      }
    }
    return result;
  }

  private runUpload(chain: AttachmentUploadChain): void {
    if (!chain.isWaveformResolved() || chain.isUploadStarted()) {
      return;
    }
    chain.markUploadStarted();
    this.recorder.record('uploadAttachment', chain.attachmentId);
  }
}

import { common } from '@kit.AbilityKit';
import { preferences } from '@kit.ArkData';
import { AttachmentUploadGraph } from '../attachment/AttachmentUploadGraph';
import { EffectRecorder } from '../common/EffectRecorder';
import { JsonMap as JsonValueMap, asMap, asMaps, cloneMap, isPresent, jsonMap as buildJsonMap, mapBoolean, mapNumber, mapText } from '../common/JsonMap';
import { IncomingWaveformValidator } from '../waveform/IncomingWaveformValidator';
import { WaveformBackupFile } from '../waveform/WaveformBackupFile';
import { WaveformGenerationService } from '../waveform/WaveformGenerationService';
import { WaveformGenerator } from '../waveform/WaveformGenerator';
import { RENDER_BAR_COUNT, SERVICE_WAVEFORM_BAR_LIMIT, isAudioAttachment } from '../waveform/WaveformLimits';
import { WaveformRenderer } from '../waveform/WaveformRenderer';
import { WaveformRecord } from '../waveform/WaveformRecord';
import { WaveformStore } from '../waveform/WaveformStore';

export type JsonMap = JsonValueMap;

export function jsonMap(keys: string[] = [], values: Object[] = []): JsonMap {
  return buildJsonMap(keys, values);
}

/** Attachment fields that never travel on an attachment pointer. */
const LOCAL_ONLY_FIELDS: string[] = ['id', 'localMedia', 'storedWaveform', 'waveform', 'waveformWorker',
  'compression', 'upload', 'durationSeconds', 'durationUs'];

/**
 * Page owner for the voice note waveform flow.
 *
 * It owns the state the page renders, the attachment waveform row, the ordered
 * log of side effects and the upload graph that gates audio uploads on waveform
 * generation.
 */
export class WaveformPageOwner {
  private input: JsonMap;
  private state: JsonMap = jsonMap();
  private readonly recorder: EffectRecorder = new EffectRecorder();
  private calls: string[] = [];
  private record?: WaveformRecord;
  private store: WaveformStore;
  private readonly generator: WaveformGenerator = new WaveformGenerator();
  private readonly renderer: WaveformRenderer = new WaveformRenderer();
  private readonly backup: WaveformBackupFile = new WaveformBackupFile();
  private readonly generation: WaveformGenerationService;
  private readonly uploads: AttachmentUploadGraph;
  private waveformBarLimit: number = SERVICE_WAVEFORM_BAR_LIMIT;
  private disposed: boolean = false;

  private constructor(store: preferences.Preferences, input: JsonMap) {
    this.store = new WaveformStore(store);
    this.input = cloneMap(input);
    this.generation = new WaveformGenerationService(this.store, this.recorder, this.generator);
    this.uploads = new AttachmentUploadGraph(this.recorder, this.generation);
  }

  static async create(context: common.UIAbilityContext, input: JsonMap): Promise<WaveformPageOwner> {
    const store: preferences.Preferences = await preferences.getPreferences(context, 'voice_waveform');
    const owner: WaveformPageOwner = new WaveformPageOwner(store, input);
    await owner.mount(input);
    return owner;
  }

  async mount(input: JsonMap): Promise<void> {
    this.input = cloneMap(input);
    this.state = jsonMap();
    this.recorder.reset();
    this.calls = ['WaveformPageOwner.mount'];
    this.record = undefined;
    this.disposed = false;
    this.uploads.reset();
    this.backup.reset();
    this.waveformBarLimit = this.resolveWaveformBarLimit();
    await this.store.clear();
    const attachment: JsonMap = this.primaryAttachment();
    if (!this.isEmpty(attachment)) {
      const attachmentId: string = mapText(attachment, 'id');
      this.state['attachmentId'] = attachmentId;
      const stored: Object | undefined = attachment['storedWaveform'];
      if (isPresent(stored)) {
        const record: WaveformRecord = WaveformRecord.fromStored(attachmentId, stored);
        await this.store.writeRecord(record);
        this.record = record;
      }
    }
    await this.store.flush();
  }

  /** Generates the waveform of the local audio attachment and persists it. */
  async generateWaveform(samples: number[], durationUs: number): Promise<void> {
    this.call('WaveformPageOwner.generateWaveform');
    const attachmentId: string = this.attachmentId();
    this.state['attachmentId'] = attachmentId;
    const record: WaveformRecord | undefined = await this.generation.run(attachmentId, samples, durationUs, true);
    if (record === undefined) {
      this.state['result'] = 'error';
      this.state['error'] = 'waveform_generation_failed';
      return;
    }
    this.record = record;
    this.state['result'] = 'success';
    this.state['storedWaveform'] = record.toPersistence();
    this.state['durationSeconds'] = record.durationSeconds;
    this.state['waveformOrigin'] = record.origin();
  }

  /** Prepares the upload of one attachment: audio waits for its waveform. */
  async startUploadGraph(): Promise<void> {
    this.call('WaveformPageOwner.startUploadGraph');
    const attachment: JsonMap = this.primaryAttachment();
    const chain = this.uploads.start(attachment, this.hasUsableWaveform(attachment));
    this.state['attachmentId'] = chain.attachmentId;
    this.state['upload'] = chain.snapshot();
  }

  /** Releases the held waveform worker and resumes the same upload chain. */
  async releaseHeldWaveform(samples: number[], durationUs: number): Promise<void> {
    this.call('WaveformPageOwner.releaseHeldWaveform');
    const attachmentId: string = mapText(this.primaryAttachment(), 'id');
    const chain = await this.uploads.release(attachmentId, samples, durationUs);
    if (chain !== undefined) {
      this.state['attachmentId'] = chain.attachmentId;
      this.state['upload'] = chain.snapshot();
    }
  }

  /** Prepares a mixed message: only its audio attachments acquire waveform work. */
  async startMixedUploadGraph(): Promise<void> {
    this.call('WaveformPageOwner.startMixedUploadGraph');
    const attachments: JsonMap[] = asMaps(this.input['attachments']);
    for (let index = 0; index < attachments.length; index++) {
      const attachment: JsonMap = attachments[index];
      this.uploads.start(attachment, this.hasUsableWaveform(attachment));
    }
    this.state['uploads'] = this.uploads.snapshot();
  }

  /** Releases the audio waveform worker of a mixed message. */
  async releaseMixedAudio(samples: number[], durationUs: number): Promise<void> {
    this.call('WaveformPageOwner.releaseMixedAudio');
    await this.uploads.releasePendingAudio(samples, durationUs);
    this.state['uploads'] = this.uploads.snapshot();
  }

  /** Serializes the outgoing attachment pointer, waveform and duration included. */
  async serializeOutgoingPointer(): Promise<void> {
    this.call('WaveformPageOwner.serializeOutgoingPointer');
    const attachment: JsonMap = this.primaryAttachment();
    const attachmentId: string = mapText(attachment, 'id');
    const pointer: JsonMap = this.buildOutgoingPointer(attachment);
    this.state['attachmentId'] = attachmentId;
    this.state['pointer'] = pointer;
    this.recorder.record('buildAttachmentPointer', attachmentId);
  }

  /** Validates an incoming envelope before any attachment state is touched. */
  async validateIncomingEnvelope(): Promise<void> {
    this.call('WaveformPageOwner.validateIncomingEnvelope');
    const pointer: JsonMap = this.incomingPointer();
    const outcome = IncomingWaveformValidator.validate(pointer, this.waveformBarLimit);
    this.state['validation'] = outcome.toMap();
    this.state['pointer'] = pointer;
    if (!outcome.accepted) {
      this.state['result'] = 'rejected';
      this.state['rejectionReason'] = outcome.reason;
      this.state['rejectedWaveformBarCount'] = outcome.barCount;
      return;
    }
    this.state['result'] = 'accepted';
    this.state['rejectionReason'] = '';
  }

  /** Imports a sender provided waveform and reloads it from the attachment store. */
  async importIncomingAttachment(): Promise<void> {
    this.call('WaveformPageOwner.importIncomingAttachment');
    const pointer: JsonMap = this.incomingPointer();
    const outcome = IncomingWaveformValidator.validate(pointer, this.waveformBarLimit);
    this.state['validation'] = outcome.toMap();
    if (!outcome.accepted) {
      this.state['result'] = 'rejected';
      this.state['rejectionReason'] = outcome.reason;
      this.state['rejectedWaveformBarCount'] = outcome.barCount;
      return;
    }
    if (pointer['audioWaveform'] === undefined || pointer['audioWaveform'] === null) {
      this.state['result'] = 'success';
      this.state['persistedAttachment'] = this.describePointer(pointer, undefined);
      this.state['reloadedAttachment'] = jsonMap();
      this.recorder.record('persistAttachment', mapText(pointer, 'cdnKey'));
      return;
    }
    const record: WaveformRecord = WaveformRecord.fromTransport(mapText(pointer, 'cdnKey'), pointer);
    await this.store.writeRecord(record);
    this.record = record;
    this.recorder.record('persistAttachment', mapText(pointer, 'cdnKey'));
    const reloaded: WaveformRecord | undefined = await this.store.readRecord();
    this.state['result'] = 'success';
    this.state['rejectionReason'] = '';
    this.state['persistedAttachment'] = this.describePointer(pointer, record);
    this.state['reloadedAttachment'] = reloaded === undefined ? jsonMap() : reloaded.toPersistence();
    this.state['durationSeconds'] = record.durationSeconds;
    this.state['waveformOrigin'] = record.origin();
  }

  /**
   * Resolves the waveform the page renders. A sender waveform is kept and
   * resampled, a locally generated waveform is regenerated when its bar count is
   * obsolete or when an interrupted generation left the empty placeholder.
   */
  async requestRenderableWaveform(samples: number[], durationUs: number): Promise<void> {
    this.call('WaveformPageOwner.requestRenderableWaveform');
    const attachment: JsonMap = this.primaryAttachment();
    const attachmentId: string = mapText(attachment, 'id');
    this.state['attachmentId'] = attachmentId;
    let record: WaveformRecord | undefined = this.currentRecordFor(attachment);
    const mediaReadable: boolean = mapText(attachment, 'localMedia') === 'readable';

    if (record !== undefined && record.isUsable()) {
      this.state['waveformOrigin'] = record.origin();
    } else {
      const staleReason: string = this.describeStaleRecord(record);
      if (!mediaReadable) {
        if (record !== undefined && record.isRenderable()) {
          this.state['waveformOrigin'] = record.origin();
          this.state['regenerationPending'] = true;
          this.state['staleReason'] = staleReason;
        } else {
          this.state['result'] = 'error';
          this.state['error'] = 'local_media_unavailable';
          this.state['staleReason'] = staleReason;
          return;
        }
      } else {
        this.recorder.record('generateWaveform', attachmentId);
        const generated: WaveformRecord | undefined = await this.generation.run(attachmentId, samples, durationUs, false);
        if (generated === undefined) {
          this.state['result'] = 'error';
          this.state['error'] = 'waveform_generation_failed';
          this.state['staleReason'] = staleReason;
          return;
        }
        record = generated;
        this.state['regenerated'] = true;
        this.state['staleReason'] = staleReason;
        this.state['persistedReplacement'] = generated.toPersistence();
        this.state['waveformOrigin'] = generated.origin();
      }
    }

    if (record === undefined) {
      this.state['result'] = 'error';
      this.state['error'] = 'waveform_unavailable';
      return;
    }
    this.record = record;
    this.state['result'] = 'success';
    this.state['renderBarCount'] = RENDER_BAR_COUNT;
    this.state['renderBars'] = this.renderer.bars(record, RENDER_BAR_COUNT);
    this.state['renderWaveform'] = this.renderer.normalized(record, RENDER_BAR_COUNT);
    this.state['durationSeconds'] = record.durationSeconds;
    this.state['renderDurationSeconds'] = record.durationSeconds;
  }

  /** Exports the attachment to a backup, clears the store and restores it. */
  async backupRestoreAndRender(): Promise<void> {
    this.call('WaveformPageOwner.backupRestoreAndRender');
    const attachment: JsonMap = this.primaryAttachment();
    const attachmentId: string = mapText(attachment, 'id');
    const record: WaveformRecord | undefined = this.currentRecordFor(attachment);
    const exported: JsonMap = this.backup.exportAttachment(attachment, record);
    this.state['attachmentId'] = attachmentId;
    this.state['exportedFilePointer'] = exported;
    this.recorder.record('exportAttachment', attachmentId);

    await this.store.clear();
    this.record = undefined;
    this.state['restoredAttachment'] = jsonMap();
    this.state['renderAfterRestore'] = jsonMap(['result'], ['error']);

    const restored: WaveformRecord | undefined = this.backup.restoreAttachment();
    if (restored === undefined) {
      this.state['result'] = 'error';
      this.state['error'] = 'backup_without_waveform';
      return;
    }
    await this.store.writeRecord(restored);
    this.recorder.record('restoreAttachment', attachmentId);
    const reloaded: WaveformRecord | undefined = await this.store.readRecord();
    const renderable: WaveformRecord = reloaded === undefined ? restored : reloaded;
    this.record = renderable;
    this.state['result'] = 'success';
    this.state['restoredAttachment'] = renderable.toPersistence();
    this.state['renderBarCount'] = RENDER_BAR_COUNT;
    this.state['renderBars'] = this.renderer.bars(renderable, RENDER_BAR_COUNT);
    this.state['renderWaveform'] = this.renderer.normalized(renderable, RENDER_BAR_COUNT);
    this.state['durationSeconds'] = renderable.durationSeconds;
    this.state['waveformOrigin'] = renderable.origin();
    this.state['renderAfterRestore'] = jsonMap(['result', 'barCount', 'renderWaveform', 'durationSeconds', 'origin'],
      ['success', RENDER_BAR_COUNT, this.renderer.normalized(renderable, RENDER_BAR_COUNT),
        renderable.durationSeconds, renderable.origin()]);
  }

  currentState(): JsonMap {
    return cloneMap(this.state);
  }

  currentEffects(): JsonMap[] {
    return this.recorder.snapshot();
  }

  currentPersistence(): JsonMap {
    return this.store.snapshot(this.record);
  }

  productionTrace(): string[] {
    return [...this.calls];
  }

  /** Reads the persisted row back, as an attachment view reload would. */
  async reopenedPersistence(): Promise<JsonMap> {
    return this.store.snapshot(await this.store.readRecord());
  }

  /** Releases the transient upload graph and flushes the attachment store. */
  async dispose(): Promise<void> {
    if (this.disposed) {
      return;
    }
    this.disposed = true;
    this.call('WaveformPageOwner.dispose');
    this.uploads.reset();
    this.backup.reset();
    await this.store.flush();
    this.state['disposed'] = true;
  }

  private buildOutgoingPointer(attachment: JsonMap): JsonMap {
    const pointer: JsonMap = jsonMap();
    const fields: string[] = Object.keys(attachment);
    for (let index = 0; index < fields.length; index++) {
      const field: string = fields[index];
      if (LOCAL_ONLY_FIELDS.indexOf(field) < 0) {
        pointer[field] = attachment[field];
      }
    }
    if (!isAudioAttachment(mapText(attachment, 'contentType'))) {
      return pointer;
    }
    const record: WaveformRecord | undefined = this.currentRecordFor(attachment);
    if (record === undefined || !record.isRenderable() || !(record.durationSeconds > 0)) {
      return pointer;
    }
    pointer['audioWaveform'] = this.magnitudesOf(record);
    pointer['audioDurationSeconds'] = record.durationSeconds;
    return pointer;
  }

  private describePointer(pointer: JsonMap, record: WaveformRecord | undefined): JsonMap {
    const described: JsonMap = jsonMap();
    const contentType: string = mapText(pointer, 'contentType');
    if (contentType.length > 0) {
      described['contentType'] = contentType;
    }
    const cdnKey: string = mapText(pointer, 'cdnKey');
    if (cdnKey.length > 0) {
      described['cdnKey'] = cdnKey;
    }
    if (record !== undefined) {
      described['barCount'] = record.barCount();
      described['audioWaveform'] = this.magnitudesOf(record);
      described['audioDurationSeconds'] = record.durationSeconds;
      described['senderProvided'] = record.isSenderProvided();
    }
    return described;
  }

  private describeStaleRecord(record: WaveformRecord | undefined): string {
    if (record === undefined) {
      return 'waveform_absent';
    }
    if (record.isPlaceholder()) {
      return 'generation_placeholder';
    }
    if (record.isObsoleteGenerated()) {
      return 'obsolete_generated_bar_count';
    }
    return 'waveform_unusable';
  }

  private currentRecordFor(attachment: JsonMap): WaveformRecord | undefined {
    const attachmentId: string = mapText(attachment, 'id');
    if (this.record !== undefined && this.record.belongsTo(attachmentId)) {
      return this.record;
    }
    const stored: Object | undefined = attachment['storedWaveform'];
    if (!isPresent(stored)) {
      return undefined;
    }
    return WaveformRecord.fromStored(attachmentId, stored);
  }

  private hasUsableWaveform(attachment: JsonMap): boolean {
    const record: WaveformRecord | undefined = this.currentRecordFor(attachment);
    return record !== undefined && record.isUsable();
  }

  private primaryAttachment(): JsonMap {
    return asMap(this.input['attachment']);
  }

  private incomingPointer(): JsonMap {
    const direct: JsonMap = asMap(this.input['incomingAttachmentPointer']);
    if (!this.isEmpty(direct)) {
      return direct;
    }
    return asMap(asMap(this.input['incomingEnvelope'])['attachmentPointer']);
  }

  private resolveWaveformBarLimit(): number {
    const configured: number = mapNumber(this.input, 'serviceWaveformLimit');
    return configured > 0 ? configured : SERVICE_WAVEFORM_BAR_LIMIT;
  }

  private magnitudesOf(record: WaveformRecord): Object {
    const magnitudes: number[] = [];
    for (let index = 0; index < record.bytes.length; index++) {
      magnitudes.push(record.bytes[index]);
    }
    return magnitudes;
  }

  private attachmentId(): string {
    return mapText(this.primaryAttachment(), 'id');
  }

  private isEmpty(value: JsonMap): boolean {
    return Object.keys(value).length === 0;
  }

  private call(name: string): void {
    this.calls.push(name);
  }
}

