import { WaveformPageOwner } from '../feature/WaveformPageOwner';

let mountedOwner: WaveformPageOwner | undefined = undefined;

export function registerWaveformPageOwner(owner: WaveformPageOwner): void {
  mountedOwner = owner;
}

export function currentWaveformPageOwner(): WaveformPageOwner | undefined {
  return mountedOwner;
}

export function releaseWaveformPageOwner(): void {
  mountedOwner = undefined;
}

import { common } from '@kit.AbilityKit';
import { jsonMap, WaveformPageOwner } from '../feature/WaveformPageOwner';
import { registerWaveformPageOwner, releaseWaveformPageOwner } from '../integration/PageOwnerRegistry';

@Entry
@Component
struct Index {
  @State status: string = 'Ready';
  @State summary: string = '';
  private owner?: WaveformPageOwner;

  async aboutToAppear(): Promise<void> {
    const context = getContext(this) as common.UIAbilityContext;
    this.owner = await WaveformPageOwner.create(context, jsonMap());
    registerWaveformPageOwner(this.owner);
    this.publish();
  }

  aboutToDisappear(): void {
    releaseWaveformPageOwner();
    void this.owner?.dispose();
    this.owner = undefined;
  }

  private fullScale(): number[] {
    const samples: number[] = [];
    for (let index = 0; index < 100; index++) {
      samples.push(32767);
    }
    return samples;
  }

  private silenceThenFullScale(): number[] {
    const samples: number[] = [];
    for (let index = 0; index < 200; index++) {
      samples.push(index < 100 ? 0 : 32767);
    }
    return samples;
  }

  private publish(): void {
    this.status = JSON.stringify(this.owner?.currentState() ?? jsonMap());
    this.summary = `attachments uploaded: ${this.owner?.currentEffects().length ?? 0} effects`;
  }

  private async generate(): Promise<void> {
    await this.owner?.generateWaveform(this.fullScale(), 2000000);
    this.publish();
  }

  private async prepareUpload(): Promise<void> {
    await this.owner?.startUploadGraph();
    await this.owner?.releaseHeldWaveform(this.fullScale(), 2000000);
    this.publish();
  }

  private async render(): Promise<void> {
    await this.owner?.requestRenderableWaveform(this.silenceThenFullScale(), 4000000);
    this.publish();
  }

  private async validateIncoming(): Promise<void> {
    await this.owner?.validateIncomingEnvelope();
    this.publish();
  }

  private async backupRestore(): Promise<void> {
    await this.owner?.backupRestoreAndRender();
    this.publish();
  }

  build() {
    Column({ space: 16 }) {
      Text('Voice note waveforms').fontSize(26).fontWeight(FontWeight.Bold)
      Button('Generate waveform').onClick(() => { void this.generate(); })
      Button('Prepare upload').onClick(() => { void this.prepareUpload(); })
      Button('Render waveform').onClick(() => { void this.render(); })
      Button('Validate incoming').onClick(() => { void this.validateIncoming(); })
      Button('Backup and restore').onClick(() => { void this.backupRestore(); })
      Text(this.summary).fontSize(14)
      Text(this.status).fontSize(14)
    }
    .width('100%')
    .height('100%')
    .padding(24)
  }
}

