import { JsonMap, asMap, asMaps, isPresent } from '../common/JsonMap';
import { MAX_BAR_MAGNITUDE } from './WaveformLimits';

/**
 * Bounded, strict view of a waveform payload that arrived from the network.
 *
 * The declared bar count is read from the payload shape first and rejected
 * against the service limit *before* any magnitude is materialised, so an
 * oversized payload fails closed instead of being expanded into memory. Only
 * genuine unsigned magnitudes survive the read: strings, booleans and nulls are
 * malformed rather than silently coerced.
 */
export class TransportWaveform {
  declaredBarCount: number = 0;
  bytes: number[] = [];
  oversized: boolean = false;
  malformed: boolean = false;
}

function strictMagnitude(item: Object): number {
  if (typeof item === 'number') {
    const value: number = item;
    if (Math.round(value) !== value || value < 0 || value > MAX_BAR_MAGNITUDE) {
      return -1;
    }
    return value;
  }
  return -1;
}

function isCount(value: Object): boolean {
  return typeof value === 'number' && Math.round(value) === value && value >= 0;
}

export function readTransportWaveform(value: Object | undefined, limit: number): TransportWaveform {
  const result: TransportWaveform = new TransportWaveform();
  if (!isPresent(value)) {
    result.malformed = true;
    return result;
  }
  if (Array.isArray(value)) {
    const items: Object[] = value as Object[];
    result.declaredBarCount = items.length;
    if (result.declaredBarCount > limit) {
      result.oversized = true;
      return result;
    }
    for (let index = 0; index < items.length; index++) {
      const magnitude: number = strictMagnitude(items[index]);
      if (magnitude < 0) {
        result.malformed = true;
        return result;
      }
      result.bytes.push(magnitude);
    }
    return result;
  }
  const source: JsonMap = asMap(value);
  const segments: JsonMap[] = asMaps(source['segments']);
  if (segments.length > 0) {
    for (let index = 0; index < segments.length; index++) {
      const count: Object = segments[index]['count'];
      if (!isCount(count)) {
        result.malformed = true;
        return result;
      }
      result.declaredBarCount += count;
      if (result.declaredBarCount > limit) {
        result.oversized = true;
        return result;
      }
    }
    for (let index = 0; index < segments.length; index++) {
      const segment: JsonMap = segments[index];
      const magnitude: number = strictMagnitude(segment['value']);
      const count: number = segments[index]['count'];
      if (magnitude < 0) {
        result.malformed = true;
        return result;
      }
      for (let bar = 0; bar < count; bar++) {
        result.bytes.push(magnitude);
      }
    }
    return result;
  }
  const barCount: Object = source['barCount'];
  if (!isCount(barCount)) {
    result.malformed = true;
    return result;
  }
  result.declaredBarCount = barCount;
  if (result.declaredBarCount > limit) {
    result.oversized = true;
    return result;
  }
  const fill: number = strictMagnitude(source['fill']);
  if (fill < 0) {
    result.malformed = true;
    return result;
  }
  for (let bar = 0; bar < result.declaredBarCount; bar++) {
    result.bytes.push(fill);
  }
  return result;
}

import { JsonMap, isEmptyMap, jsonMap, mapNumber, mapText } from '../common/JsonMap';
import { TransportWaveform, readTransportWaveform } from './TransportWaveform';

/**
 * Outcome of validating the waveform metadata of an incoming attachment
 * pointer. `bytes` is only populated once the payload has been accepted.
 */
export class IncomingWaveformOutcome {
  accepted: boolean = false;
  reason: string = '';
  barCount: number = 0;
  limit: number = 0;
  durationSeconds: number = 0;
  bytes: number[] = [];

  constructor(limit: number) {
    this.limit = limit;
  }

  toMap(): JsonMap {
    return jsonMap(['accepted', 'reason', 'barCount', 'limit', 'durationSeconds'],
      [this.accepted, this.reason, this.barCount, this.limit, this.durationSeconds]);
  }
}

/**
 * Envelope validation for incoming attachment pointers. Waveform metadata is
 * checked before the attachment is persisted or handed to the renderer, so a
 * malformed or oversized sender payload can never contaminate attachment state.
 */
export class IncomingWaveformValidator {
  static validate(pointer: JsonMap, limit: number): IncomingWaveformOutcome {
    const outcome: IncomingWaveformOutcome = new IncomingWaveformOutcome(limit);
    if (isEmptyMap(pointer)) {
      outcome.reason = 'missing_attachment_pointer';
      return outcome;
    }
    if (mapText(pointer, 'cdnKey').length === 0) {
      outcome.reason = 'missing_cdn_key';
      return outcome;
    }
    const waveform: Object | undefined = pointer['audioWaveform'];
    if (waveform === undefined || waveform === null) {
      outcome.accepted = true;
      return outcome;
    }
    const transport: TransportWaveform = readTransportWaveform(waveform, outcome.limit);
    outcome.barCount = transport.declaredBarCount;
    outcome.durationSeconds = mapNumber(pointer, 'audioDurationSeconds');
    if (transport.oversized) {
      outcome.reason = 'audio_waveform_too_large';
      return outcome;
    }
    if (transport.malformed) {
      outcome.reason = 'malformed_audio_waveform';
      return outcome;
    }
    if (!(outcome.durationSeconds > 0)) {
      outcome.reason = 'missing_audio_duration';
      return outcome;
    }
    outcome.bytes = transport.bytes;
    outcome.accepted = true;
    return outcome;
  }
}

